1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface Damage {
13	  itemType: string;
14	  amount: number;
15	}
16	
17	export interface Incident {
18	  cause: string;
19	  damages: Damage[];
20	}
21	
22	export type Step =
23	  | { op: "quote"; items: Item[] }
24	  | { op: "claim"; policy: number; incident: Incident };
25	
26	export interface Scenario {
27	  customer: Customer;
28	  steps: Step[];
29	}
30	
31	export type StepResult =
32	  | { premium: number }
33	  | { payout: number; remainingCap: number };
34	
35	export interface ScenarioResult {
36	  results: StepResult[];
37	}
38	
39	const PROCESSING_FEE = 5;
40	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
41	
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	// MHPCO always rounds in its own favour: money it receives rounds up,
46	// money it pays out rounds down.
47	const roundIncomingInMHPCOsFavour = Math.ceil;
48	const roundOutgoingInMHPCOsFavour = Math.floor;
49	
50	const sumOf = <T>(values: T[], amountOf: (value: T) => number): number =>
51	  values.reduce((sum, value) => sum + amountOf(value), 0);
52	
53	const BASE_PREMIUM_BY_ITEM_TYPE = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	} as const satisfies Record<string, number>;
61	
62	type InsurableItemType = keyof typeof BASE_PREMIUM_BY_ITEM_TYPE;
63	
64	const BLOCK_SIZE = 3;
65	const BLOCK_BASE_PREMIUM = 60;
66	const CURSE_SURCHARGE_PERCENT = 50;
67	const HIGH_ENCHANTMENT_THRESHOLD = 5;
68	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
69	const LOYALTY_THRESHOLD_YEARS = 2;
70	const LOYALTY_DISCOUNT_PERCENT = 20;
71	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
72	
73	const basePremiumOf = (item: Item): number =>
74	  BASE_PREMIUM_BY_ITEM_TYPE[item.type as InsurableItemType];
75	
76	interface RiskSurcharge {
77	  appliesTo: (item: Item) => boolean;
78	  percent: number;
79	}
80	
81	const RISK_SURCHARGES: RiskSurcharge[] = [
82	  { appliesTo: (item) => item.cursed === true, percent: CURSE_SURCHARGE_PERCENT },
83	  {
84	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
85	    percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
86	  },
87	];
88	
89	const itemSurcharge = (item: Item): number =>
90	  sumOf(
91	    RISK_SURCHARGES.filter((surcharge) => surcharge.appliesTo(item)),
92	    (surcharge) => percentOf(basePremiumOf(item), surcharge.percent),
93	  );
94	
95	const policySurcharges = (items: Item[]): number => sumOf(items, itemSurcharge);
96	
97	const groupByType = (items: Item[]): Item[][] => [
98	  ...items
99	    .reduce(
100	      (groups, item) =>
101	        groups.set(item.type, [...(groups.get(item.type) ?? []), item]),
102	      new Map<string, Item[]>(),
103	    )
104	    .values(),
105	];
106	
107	const basePremiumOfGroup = (group: Item[]): number =>
108	  group.length === BLOCK_SIZE
109	    ? BLOCK_BASE_PREMIUM
110	    : sumOf(group, basePremiumOf);
111	
112	const policyBasePremium = (items: Item[]): number =>
113	  sumOf(groupByType(items), basePremiumOfGroup);
114	
115	interface QuoteContext {
116	  customer: Customer;
117	  previousQuotes: number;
118	}
119	
120	const isLoyal = ({ customer }: QuoteContext): boolean =>
121	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
122	
123	const isFollowUpContract = ({ previousQuotes }: QuoteContext): boolean =>
124	  previousQuotes > 0;
125	
126	interface PolicyAdjustment {
127	  appliesTo: (context: QuoteContext) => boolean;
128	  percent: number;
129	}
130	
131	const POLICY_ADJUSTMENTS: PolicyAdjustment[] = [
132	  { appliesTo: () => true, percent: FIRST_INSURANCE_SURCHARGE_PERCENT },
133	  { appliesTo: isLoyal, percent: -LOYALTY_DISCOUNT_PERCENT },
134	  { appliesTo: isFollowUpContract, percent: -FOLLOW_UP_DISCOUNT_PERCENT },
135	];
136	
137	const policyAdjustments = (policyBase: number, context: QuoteContext): number =>
138	  sumOf(
139	    POLICY_ADJUSTMENTS.filter((adjustment) => adjustment.appliesTo(context)),
140	    (adjustment) => percentOf(policyBase, adjustment.percent),
141	  );
142	
143	const quotePremium = (items: Item[], context: QuoteContext): number => {
144	  const policyBase = policyBasePremium(items);
145	  const premiumBeforeFee =
146	    policyBase + policySurcharges(items) + policyAdjustments(policyBase, context);
147	  return roundIncomingInMHPCOsFavour(premiumBeforeFee + PROCESSING_FEE);
148	};
149	
150	const INSURANCE_VALUE_BY_ITEM_TYPE = {
151	  sword: 1000,
152	  amulet: 600,
153	  staff: 800,
154	  potion: 400,
155	  rune: 250,
156	  moonstone: 250,
157	} as const satisfies Record<InsurableItemType, number>;
158	
159	const DEDUCTIBLE_PER_DAMAGE = 100;
160	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
161	
162	const insuranceValueOf = (item: Item): number =>
163	  INSURANCE_VALUE_BY_ITEM_TYPE[item.type as InsurableItemType];
164	
165	const policyCapOf = (items: Item[]): number =>
166	  CAP_MULTIPLE_OF_INSURANCE_SUM * sumOf(items, insuranceValueOf);
167	
168	const HALVING_ENCHANTMENT_THRESHOLD = 8;
169	const HALVED_REIMBURSEMENT_PERCENT = 50;
170	
171	const isHighlyEnchanted = (item: Item | undefined): boolean =>
172	  (item?.enchantment ?? 0) >= HALVING_ENCHANTMENT_THRESHOLD;
173	
174	const reimbursementPercentFor = (item: Item | undefined): number =>
175	  isHighlyEnchanted(item) ? HALVED_REIMBURSEMENT_PERCENT : 100;
176	
177	const insuredItemFor = (damage: Damage, insured: Item[]): Item | undefined =>
178	  insured.find(({ type }) => type === damage.itemType);
179	
180	const reimbursementFor = (damage: Damage, insured: Item[]): number =>
181	  percentOf(
182	    damage.amount,
183	    reimbursementPercentFor(insuredItemFor(damage, insured)),
184	  ) - DEDUCTIBLE_PER_DAMAGE;
185	
186	const policyOf = (step: Extract<Step, { op: "claim" }>, steps: Step[]) => {
187	  const policy = steps[step.policy];
188	  if (policy?.op !== "quote") throw new Error("claim references no policy");
189	  return policy;
190	};
191	
192	// A claim consumes part of its policy's cap, so each policy carries a
193	// remaining cap that later claims against the same policy draw down.
194	type RemainingCapByPolicy = ReadonlyMap<number, number>;
195	
196	// Settling a claim is a state transition: it reports what the customer is
197	// paid and what the policy has left. The caller owns the running state.
198	const settleClaim = (
199	  step: Extract<Step, { op: "claim" }>,
200	  steps: Step[],
201	  remainingCaps: RemainingCapByPolicy,
202	): { payout: number; remainingCap: number } => {
203	  const insured = policyOf(step, steps).items;
204	  const desiredPayout = roundOutgoingInMHPCOsFavour(
205	    sumOf(step.incident.damages, (damage) => reimbursementFor(damage, insured)),
206	  );
207	  const capBeforeClaim =
208	    remainingCaps.get(step.policy) ?? policyCapOf(insured);
209	  const payout = Math.min(desiredPayout, capBeforeClaim);
210	  return { payout, remainingCap: capBeforeClaim - payout };
211	};
212	
213	const countQuotesBefore = (steps: Step[], index: number): number =>
214	  steps.slice(0, index).filter((step) => step.op === "quote").length;
215	
216	export const runScenario = ({ customer, steps }: Scenario): ScenarioResult => {
217	  // The one place that owns the running cap state: settleClaim reports each
218	  // policy's new remaining cap, and the write back happens here, in plain sight.
219	  const remainingCaps = new Map<number, number>();
220	  return {
221	    results: steps.map((step, index) => {
222	      if (step.op === "quote") {
223	        const context = {
224	          customer,
225	          previousQuotes: countQuotesBefore(steps, index),
226	        };
227	        return { premium: quotePremium(step.items, context) };
228	      }
229	      const result = settleClaim(step, steps, remainingCaps);
230	      remainingCaps.set(step.policy, result.remainingCap);
231	      return result;
232	    }),
233	  };
234	};
